before:
static func hasSupportedCrew(_ ship: CatalogueShip) -> Bool {
  if let native = ship.nativeHull,
    [.thargoid, .thargon, .station, .asteroid, .cargo, .missile].contains(native)
  {
    return false
  }
  let name = ship.name.lowercased()
  return !["thargoid", "thargon", "drone", "satellite"].contains(where: name.contains)
}

proposedAfter:
/// Declared native crew class; conversion places never issue native people.
static func hasSupportedCrew(_ ship: CatalogueShip) -> Bool {
  guard let source = OriginalFleetR3Data.contract(for: ship.id),
    source.objectKind == .ship, ship.catalogue.objectKind == .ship,
    source.name == ship.name, source.family == ship.catalogue.family,
    source.origin.catalogueOrigin == ship.catalogue.origin,
    let crew = source.accommodation
  else { return false }
  return crew.nativeCrew > 0
}
